Here is the root cause:
The `igc_clean_tx_ring` function in `igc_main.c` did not clear XSK TX timestamp references when cleaning a TX ring. This left stale `xsk_meta` pointers in the timestamp registers, which later caused a page fault when the interrupt handler attempted to dereference them.

Here is the patch:
  */
 static void igc_clean_tx_ring(struct igc_ring *tx_ring)
 {
 	u16 i = tx_ring->next_to_clean;
 	struct igc_tx_buffer *tx_buffer = &tx_ring->tx_buffer_info[i];
 	u32 xsk_frames = 0;

 	while (i != tx_ring->next_to_use) {
 		union igc_adv_tx_desc *eop_desc, *tx_desc;

 		switch (tx_buffer->type) {
 		case IGC_TX_BUFFER_TYPE_XSK:
 			xsk_frames++;
 			break;
 		case IGC_TX_BUFFER_TYPE_XDP:
 			xdp_return_frame(tx_buffer->xdpf);
 			igc_unmap_tx_buffer(tx_ring->dev, tx_buffer);
 			break;
 		case IGC_TX_BUFFER_TYPE_SKB:
 			dev_kfree_skb_any(tx_buffer->skb);
 			igc_unmap_tx_buffer(tx_ring->dev, tx_buffer);
 			break;
 		default:
 			netdev_warn_once(tx_ring->netdev, "Unknown Tx buffer type\n");
 			break;
 		}

 		/* check for eop_desc to determine the end of the packet */
 		eop_desc = tx_buffer->next_to_watch;
 		tx_desc = IGC_TX_DESC(tx_ring, i);

 		/* unmap remaining buffers */
 		while (tx_desc != eop_desc) {
 			tx_buffer++;
 			tx_desc++;
 			i++;
 			if (unlikely(i == tx_ring->count)) {
 				i = 0;
 				tx_buffer = tx_ring->tx_buffer_info;
 				tx_desc = IGC_TX_DESC(tx_ring, 0);
 			}

 			/* unmap any remaining paged data */
 			if (dma_unmap_len(tx_buffer, len))
 				igc_unmap_tx_buffer(tx_ring->dev, tx_buffer);
 		}

 		tx_buffer->next_to_watch = NULL;

 		/* move us one more past the eop_desc for start of next pkt */
 		tx_buffer++;
 		i++;
 		if (unlikely(i == tx_ring->count)) {
 			i = 0;
 			tx_buffer = tx_ring->tx_buffer_info;
 		}
 	}

 	if (tx_ring->xsk_pool && xsk_frames)
 		xsk_tx_completed(tx_ring->xsk_pool, xsk_frames);

 	/* reset BQL for queue */
 	netdev_tx_reset_queue(txring_txq(tx_ring));

 	/* Zero out the buffer ring */
 	memset(tx_ring->tx_buffer_info, 0,
 	       sizeof(*tx_ring->tx_buffer_info) * tx_ring->count);

 	/* Zero out the descriptor ring */
 	memset(tx_ring->desc, 0, tx_ring->size);

 	/* reset next_to_use and next_to_clean */
 	tx_ring->next_to_use = 0;
 	tx_ring->next_to_clean = 0;
+
